
import type { LocationAddressInput } from './LocationAddressInput.js';
import type { LocationCoordinateInput } from './LocationCoordinateInput.js';
import type { LocationInventoryInput } from './LocationInventoryInput.js';

/** A physical or logical place a merchant operates from. Locations own geography and, when inventory is enabled, an inventory capability block. */ export type LocationInput = { /** Published postal address. */ "address"?: LocationAddressInput; /** Published geographic coordinate. */ "coordinate"?: LocationCoordinateInput; /** Source of the stored latitude and longitude. */ "coordinate_source"?: "merchant_supplied" | "geocoded" | null; /** Time the Location was created. Format: date-time. */ "created_at": string | globalThis.Date; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; /** Optimistic-concurrency revision for geography writes. Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 0. */ "geography_revision": string; /** Inventory allocation capability at this Location. */ "inventory"?: LocationInventoryInput; /** Stable Location ID. */ "location_id": string; /** Caller-owned metadata. */ "metadata": Record<string, string>; /** Merchant-facing Location name. */ "name": string; /** Provider-normalized address used for geography evaluation. */ "normalized_address"?: LocationAddressInput; /** Current Location lifecycle status. */ "status": "active" | "inactive" | "archived"; /** IANA timezone for local schedules. */ "timezone": string; /** Time the Location last changed. Format: date-time. */ "updated_at": string | globalThis.Date; /** Address validation status. */ "validation_status": "not_validated" | "validated" | "merchant_verified"; /** Optimistic-concurrency version for general Location writes. Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 0. */ "version": string; };
